/* Flashcard deck — built from /sections/deep-dives/. Study aids; verify against authority.
   Fields: id, section, area, tag, front, back */
window.CPA_CARDS = [

/* ============================== FAR ============================== */
{ id:"FAR-001", section:"FAR", area:"III", tag:"Revenue (ASC 606)",
  front:"List the ASC 606 five-step revenue model in order.",
  back:"1) Identify the contract → 2) Identify the performance obligations → 3) Determine the transaction price → 4) Allocate the price to POs (relative standalone selling price) → 5) Recognize revenue as/when each PO is satisfied." },
{ id:"FAR-002", section:"FAR", area:"III", tag:"Revenue (ASC 606)",
  front:"What are the THREE criteria for recognizing revenue OVER TIME (any one suffices)?",
  back:"(a) Customer simultaneously receives & consumes the benefits as you perform; (b) your performance creates/enhances an asset the customer controls; (c) the asset has no alternative use to you AND you have an enforceable right to payment for performance to date. Otherwise: point in time when control transfers." },
{ id:"FAR-003", section:"FAR", area:"III", tag:"Revenue (ASC 606)",
  front:"Two methods to estimate variable consideration, and the constraint that applies?",
  back:"Expected value (probability-weighted) or most likely amount. Constraint: include variable consideration only to the extent it is HIGHLY PROBABLE that a significant revenue reversal will not occur." },
{ id:"FAR-004", section:"FAR", area:"III", tag:"Revenue (ASC 606)",
  front:"How is consideration payable to a customer (e.g., a slotting fee) treated?",
  back:"As a REDUCTION of revenue — unless it is payment for a distinct good or service from the customer (then treat like a normal purchase)." },
{ id:"FAR-005", section:"FAR", area:"III", tag:"Revenue (ASC 606)",
  front:"Accounting for sales with a right of return?",
  back:"Recognize revenue NET of expected returns; record a refund liability and an asset for the right to recover the goods (at former carrying amount less recovery costs)." },
{ id:"FAR-006", section:"FAR", area:"III", tag:"Leases (ASC 842)",
  front:"The five lessee finance-lease classification criteria (any ONE makes it a finance lease)?",
  back:"OWNES: Ownership transfers at end; Written purchase option reasonably certain to exercise; NPV of payments ≥ substantially all (~90%) of fair value; Economic life — term ≥ major part (~75%) of remaining life; Specialized asset with no alternative use to the lessor." },
{ id:"FAR-007", section:"FAR", area:"III", tag:"Leases (ASC 842)",
  front:"Finance vs. operating lease — what differs on the lessee's income statement?",
  back:"Both record an ROU asset and lease liability at PV of payments. FINANCE: separate amortization + interest → front-loaded total expense. OPERATING: single straight-line lease expense → level expense." },
{ id:"FAR-008", section:"FAR", area:"III", tag:"Leases (ASC 842)",
  front:"Lease liability rollforward formula?",
  back:"Ending liability = Beginning liability + interest (beginning balance × rate) − payment." },
{ id:"FAR-009", section:"FAR", area:"I", tag:"Cash flows",
  front:"Indirect method: what do you do with depreciation, a gain on sale, and an increase in A/R?",
  back:"Depreciation: ADD back (non-cash). Gain on sale: SUBTRACT from NI (full proceeds go to investing). Increase in A/R: SUBTRACT (asset up = cash down)." },
{ id:"FAR-010", section:"FAR", area:"I", tag:"Cash flows",
  front:"Working-capital memory rule for the indirect method?",
  back:"Operating ASSET up → cash down (subtract); operating asset down → add. Operating LIABILITY up → cash up (add); liability down → subtract." },
{ id:"FAR-011", section:"FAR", area:"I", tag:"Cash flows",
  front:"US GAAP classification: interest paid, interest received, dividends received, dividends paid?",
  back:"Interest paid, interest received, and dividends received = OPERATING. Dividends paid = FINANCING. (Proceeds from selling PP&E = investing, including the full proceeds.)" },
{ id:"FAR-012", section:"FAR", area:"III", tag:"Income taxes",
  front:"Permanent vs. temporary difference — give two examples of each.",
  back:"Permanent (never reverse; no deferred tax): municipal bond interest, fines/penalties, federal income tax expense, nondeductible meals portion. Temporary (reverse; create DTA/DTL): depreciation differences (MACRS vs. book), warranty/bad-debt accruals, deferred revenue, NOL carryforwards." },
{ id:"FAR-013", section:"FAR", area:"III", tag:"Income taxes",
  front:"Accelerated tax depreciation (MACRS > book) creates a DTA or DTL? Why?",
  back:"DTL — taxable income is LOWER now and will be HIGHER later when the difference reverses." },
{ id:"FAR-014", section:"FAR", area:"III", tag:"Income taxes",
  front:"When is a valuation allowance recorded against a DTA?",
  back:"When it is MORE LIKELY THAN NOT (>50%) that some or all of the DTA will NOT be realized." },
{ id:"FAR-015", section:"FAR", area:"II", tag:"Receivables",
  front:"What does CECL (ASC 326) require for trade receivables?",
  back:"Recognize EXPECTED credit losses over the asset's life at initial recognition (allowance method based on historical loss data, current conditions, and reasonable & supportable forecasts) — not incurred losses." },
{ id:"FAR-016", section:"FAR", area:"II", tag:"Inventory",
  front:"Inventory measurement: which methods use lower of cost or NET REALIZABLE VALUE vs. lower of cost or MARKET?",
  back:"FIFO and average cost: lower of cost or NRV. LIFO and retail method: lower of cost or market (market = replacement cost, capped by NRV ceiling and NRV-minus-normal-profit floor)." },
{ id:"FAR-017", section:"FAR", area:"II", tag:"Debt",
  front:"Effective-interest method: interest expense and discount amortization each period?",
  back:"Interest expense = carrying amount × market (effective) rate at issuance. Cash paid = face × stated rate. Discount amortization = expense − cash; carrying amount moves toward face over the term." },
{ id:"FAR-018", section:"FAR", area:"II", tag:"Intangibles",
  front:"How are goodwill and finite-lived intangibles treated after acquisition?",
  back:"Goodwill: NOT amortized; tested for impairment (at the reporting-unit level). Finite-lived intangibles: amortized over useful life and tested for impairment when indicators exist." },
{ id:"FAR-019", section:"FAR", area:"III", tag:"Fair value",
  front:"Fair value hierarchy Levels 1–3?",
  back:"Level 1: quoted prices in active markets for identical items. Level 2: observable inputs other than Level 1 (similar items, quoted in inactive markets, observable rates). Level 3: unobservable inputs (entity's own assumptions)." },
{ id:"FAR-020", section:"FAR", area:"III", tag:"Subsequent events",
  front:"Recognized vs. nonrecognized subsequent events?",
  back:"Recognized (Type 1): condition EXISTED at the balance-sheet date → adjust the statements (e.g., customer bankruptcy confirming a bad debt). Nonrecognized (Type 2): condition arose AFTER → disclose only (e.g., fire, debt issuance, business combination)." },
{ id:"FAR-021", section:"FAR", area:"III", tag:"Accounting changes",
  front:"Treatment of: change in estimate, change in principle, error correction?",
  back:"Estimate: PROSPECTIVE (current + future). Principle: RETROSPECTIVE (adjust prior periods presented; cumulative effect to beginning RE). Error: RESTATEMENT of prior statements (prior-period adjustment)." },
{ id:"FAR-022", section:"FAR", area:"I", tag:"NFP",
  front:"NFP net asset classes and the statement that shows expenses two ways?",
  back:"Two classes: net assets WITHOUT donor restrictions and WITH donor restrictions. The statement of functional expenses shows expenses by FUNCTION (program/support) and by NATURAL classification." },
{ id:"FAR-023", section:"FAR", area:"I", tag:"NFP",
  front:"When are NFP contributions and unconditional promises (pledges) recognized?",
  back:"When the unconditional promise is received — at fair value; restriction (purpose/time) classifies it as 'with donor restrictions,' releasing to 'without' when satisfied. Conditional promises wait until conditions are substantially met." },
{ id:"FAR-024", section:"FAR", area:"I", tag:"Governmental",
  front:"The three fund categories and examples of each?",
  back:"GOVERNMENTAL: General, Special Revenue, Capital Projects, Debt Service, Permanent. PROPRIETARY: Enterprise, Internal Service. FIDUCIARY: Custodial, Pension/OPEB trust, Investment trust, Private-purpose trust." },
{ id:"FAR-025", section:"FAR", area:"I", tag:"Governmental",
  front:"Measurement focus/basis: government-wide vs. governmental fund statements?",
  back:"Government-wide: economic resources, FULL ACCRUAL. Governmental funds: current financial resources, MODIFIED ACCRUAL — revenue when measurable AND available; no capital assets or long-term debt on the fund balance sheet." },
{ id:"FAR-026", section:"FAR", area:"I", tag:"Governmental",
  front:"Two classic reconciling items from fund balance to government-wide net position?",
  back:"ADD capital assets (net of accumulated depreciation) — funds expensed them as outlay; SUBTRACT long-term liabilities (bonds, compensated absences) — not reported in funds. Also: accrual adjustments, internal service funds, deferred inflows." },
{ id:"FAR-027", section:"FAR", area:"II", tag:"Equity",
  front:"Cost method treasury stock: purchase and reissue above cost?",
  back:"Purchase: debit Treasury Stock at cost (contra-equity). Reissue above cost: cash for proceeds, credit treasury stock at cost, excess to APIC—Treasury Stock. No gains/losses ever hit income." },
{ id:"FAR-028", section:"FAR", area:"I", tag:"Consolidation",
  front:"When do you consolidate, and what happens to intercompany balances?",
  back:"Consolidate when you have CONTROL (generally >50% voting interest or primary beneficiary of a VIE). Eliminate ALL intercompany balances and transactions (receivables/payables, sales, profit in ending inventory) in consolidation." },
{ id:"FAR-029", section:"FAR", area:"I", tag:"OCI",
  front:"Name four items reported in Other Comprehensive Income.",
  back:"Foreign-currency translation adjustments; unrealized gains/losses on cash-flow-hedge derivatives (effective portion); unrealized G/L on available-for-sale DEBT securities; pension remeasurements (prior service cost, gains/losses)." },
{ id:"FAR-030", section:"FAR", area:"II", tag:"PP&E",
  front:"Impairment test for held-and-used long-lived assets (US GAAP)?",
  back:"Two steps: (1) Recoverability — carrying amount vs. UNDISCOUNTED future cash flows; if carrying > undiscounted CF, then (2) impairment loss = carrying amount − FAIR VALUE. No reversal of impairments for held-and-used assets." },

/* ============================== AUD ============================== */
{ id:"AUD-001", section:"AUD", area:"I", tag:"Method",
  front:"What is the first move on almost every AUD question?",
  back:"Label the engagement: (1) engagement type (audit / review / compilation / prep / attestation / SOC), (2) issuer vs. nonissuer + reporting framework, (3) then derive the evidence or reporting consequence. The governing authority follows from the label." },
{ id:"AUD-002", section:"AUD", area:"I", tag:"Authority",
  front:"Which standards govern: issuer audit, nonissuer audit, review of a nonissuer, attestation, government audit?",
  back:"Issuer audit: PCAOB (+ SEC independence). Nonissuer audit: AICPA SAS. Review/compilation/prep of nonissuer: SSARS. Attestation/AUP/SOC: SSAE. Government/single audit: GAO Yellow Book + Uniform Guidance (+ AICPA)." },
{ id:"AUD-003", section:"AUD", area:"I", tag:"Independence",
  front:"Independence requirements: audit, review, compilation, preparation?",
  back:"Audit and review: independence REQUIRED. Compilation: NOT required, but lack of independence must be DISCLOSED in the report. Preparation: not required (no report, no assurance)." },
{ id:"AUD-004", section:"AUD", area:"I", tag:"Independence",
  front:"Name the seven independence threats in the AICPA conceptual framework.",
  back:"Self-review, advocacy, adverse interest, familiarity, undue influence, self-interest, management participation. If no safeguard reduces a threat to an acceptable level → independence is impaired." },
{ id:"AUD-005", section:"AUD", area:"IV", tag:"Reports",
  front:"The 2×2 opinion matrix: misstatement vs. scope limitation × pervasive or not?",
  back:"Material misstatement, not pervasive → QUALIFIED. Misstatement, pervasive → ADVERSE. Scope limitation, not pervasive → QUALIFIED. Scope limitation, pervasive → DISCLAIMER." },
{ id:"AUD-006", section:"AUD", area:"IV", tag:"Reports",
  front:"Emphasis-of-Matter vs. Other-Matter paragraph?",
  back:"EOM: about something appropriately presented IN the F/S but fundamental to understanding (going concern, special-purpose framework, major subsequent event). OM: relevant to users but NOT presented in the F/S (predecessor auditor, restricted use)." },
{ id:"AUD-007", section:"AUD", area:"IV", tag:"Reports",
  front:"KAMs vs. CAMs?",
  back:"KAMs (Key Audit Matters): AICPA/nonissuer — communicated only when ENGAGED to report them. CAMs (Critical Audit Matters): PCAOB/issuer — REQUIRED; matters communicated to the audit committee involving especially challenging, subjective, or complex judgment. PCAOB reports also state auditor tenure." },
{ id:"AUD-008", section:"AUD", area:"IV", tag:"SSARS",
  front:"What procedures and assurance does a REVIEW provide?",
  back:"Inquiry + analytical procedures ('I-A') → LIMITED (negative) assurance: 'not aware of any material modifications.' No tests of controls, no corroborating evidence like an audit." },
{ id:"AUD-009", section:"AUD", area:"IV", tag:"Attestation",
  front:"Agreed-upon procedures engagement — what does the report express?",
  back:"FINDINGS only — no opinion, no assurance conclusion. The practitioner performs procedures specified by the engaging parties; users draw their own conclusions. Governed by SSAE; independence required." },
{ id:"AUD-010", section:"AUD", area:"II", tag:"COSO",
  front:"COSO's five components of internal control?",
  back:"Control Environment, Risk Assessment, Control Activities, Information & Communication, Monitoring Activities (17 principles across them). Control environment is the foundation — tone at the top." },
{ id:"AUD-011", section:"AUD", area:"II", tag:"Deficiencies",
  front:"Deficiency vs. significant deficiency vs. material weakness?",
  back:"Deficiency: control doesn't prevent/detect misstatements timely. Significant deficiency: less severe than MW but important enough to merit attention of those charged with governance. Material weakness: reasonable possibility a MATERIAL misstatement won't be prevented/detected timely." },
{ id:"AUD-012", section:"AUD", area:"II", tag:"Controls",
  front:"ITGC vs. application controls?",
  back:"ITGCs: general controls the applications depend on — access security, change management, computer operations. Application controls: automated controls within a specific process (edit checks, matching, approvals). ITGC failures undermine reliance on application controls." },
{ id:"AUD-013", section:"AUD", area:"II", tag:"SOC 1",
  front:"User auditor wants to rely on a service organization's controls — which report?",
  back:"SOC 1 TYPE 2 — it covers design AND operating effectiveness over a period, which is what control reliance requires. Type 1 (design at a point in time) supports understanding only." },
{ id:"AUD-014", section:"AUD", area:"II", tag:"Materiality",
  front:"Materiality vs. performance materiality vs. tolerable misstatement?",
  back:"Materiality: F/S-level threshold. Performance materiality: amount(s) set LOWER to reduce the risk that aggregate uncorrected/undetected misstatements exceed materiality. Tolerable misstatement: application of performance materiality to a sampling procedure." },
{ id:"AUD-015", section:"AUD", area:"II", tag:"Fraud",
  front:"The fraud triangle?",
  back:"Incentive/pressure, Opportunity, Rationalization/attitude. Presumed fraud risks: improper revenue recognition and management override of controls." },
{ id:"AUD-016", section:"AUD", area:"III", tag:"Assertions",
  front:"Testing direction: existence vs. completeness?",
  back:"Existence (overstatement concern): recorded → supporting evidence (vouch FROM the books). Completeness (understatement concern): source documents/population → recorded (trace TO the books)." },
{ id:"AUD-017", section:"AUD", area:"III", tag:"Sampling",
  front:"Attributes vs. variables sampling — what does each test?",
  back:"Attributes: tests CONTROLS — deviation RATE vs. tolerable rate. Variables (incl. MUS/PPS, classical): substantive tests — DOLLAR misstatement vs. tolerable misstatement." },
{ id:"AUD-018", section:"AUD", area:"III", tag:"Sampling",
  front:"Effect on sample size: higher tolerable rate? higher expected deviation? higher confidence?",
  back:"Higher tolerable rate/misstatement → SMALLER sample. Higher expected deviation/misstatement → LARGER. Higher desired confidence (lower acceptable risk) → LARGER. Population size: minimal effect." },
{ id:"AUD-019", section:"AUD", area:"III", tag:"Sampling",
  front:"Key characteristics of MUS / PPS sampling?",
  back:"Each DOLLAR is a sampling unit → automatically biases toward larger items; efficient for testing OVERSTATEMENT; awkward for zero/negative balances and understatement detection." },
{ id:"AUD-020", section:"AUD", area:"III", tag:"Confirmations",
  front:"Positive vs. negative A/R confirmations — when is negative acceptable?",
  back:"Positive: respond either way (use for large/risky balances). Negative: respond only if you DISAGREE — acceptable only when RMM is low, items are small and numerous, and recipients are likely to read them." },
{ id:"AUD-021", section:"AUD", area:"III", tag:"Going concern",
  front:"Substantial doubt about going concern exists and disclosure is adequate — report effect?",
  back:"Unmodified opinion + a separate 'Substantial Doubt About Going Concern' (emphasis) section. If disclosure is INADEQUATE → it's a misstatement → qualified or adverse." },
{ id:"AUD-022", section:"AUD", area:"III", tag:"Rep letter",
  front:"Management representation letter — who signs and as of what date?",
  back:"CEO + CFO (those responsible for the F/S), dated AS OF the auditor's report date, covering all periods in the report. Refusal to sign = scope limitation (usually disclaimer/withdrawal)." },
{ id:"AUD-023", section:"AUD", area:"III", tag:"Evidence",
  front:"Rank evidence reliability (general hierarchy).",
  back:"Auditor's direct personal knowledge (observation/recalculation/inspection by auditor) > external evidence sent directly to auditor (confirmations) > external evidence held by client > internal client-generated evidence. Effective controls increase reliability of internal evidence." },
{ id:"AUD-024", section:"AUD", area:"III", tag:"Analytics",
  front:"When are analytical procedures REQUIRED in an audit?",
  back:"At RISK ASSESSMENT (planning) and near the END (overall review/forming conclusion). As substantive procedures they are optional." },
{ id:"AUD-025", section:"AUD", area:"I", tag:"Documentation",
  front:"Audit documentation retention periods?",
  back:"AICPA (nonissuer): at least 5 years from report release date. PCAOB (issuer): 7 years. Documentation completion: 60 days (AICPA) / 45 days (PCAOB) after release." },
{ id:"AUD-026", section:"AUD", area:"I", tag:"Acceptance",
  front:"Before accepting an audit, the auditor should… (name three preconditions/steps)",
  back:"Determine framework acceptability; obtain management's acknowledgment of its responsibilities (F/S, internal control, access); assess independence & competence; communicate with the predecessor auditor (with client permission); establish terms in an engagement letter." },
{ id:"AUD-027", section:"AUD", area:"II", tag:"Risk model",
  front:"The audit risk model and how detection risk responds?",
  back:"AR = IR × CR × DR (RMM = IR × CR). Audit risk is held low; as assessed RMM rises, acceptable DETECTION risk falls → more persuasive, more extensive, better-timed substantive procedures." },
{ id:"AUD-028", section:"AUD", area:"III", tag:"Subsequent events",
  front:"Auditor's responsibility for subsequent events after the report date?",
  back:"No obligation to keep inquiring after the report date; but if facts discovered that existed at the report date and would have changed the report, assess, discuss with management, and act (revision/disclosure). Dual-date if extending work on one event only." },
{ id:"AUD-029", section:"AUD", area:"I", tag:"Quality",
  front:"Engagement quality review — what is it?",
  back:"An objective evaluation by a qualified reviewer (not on the team) of significant judgments and conclusions before the report is released — part of the firm's quality management system; required for issuer audits." },
{ id:"AUD-030", section:"AUD", area:"III", tag:"Estimates",
  front:"Three approaches to auditing an accounting estimate?",
  back:"(1) Test how management made it (method, data, assumptions); (2) develop an independent expectation; (3) use events after period-end up to the report date as evidence. Watch for management bias." },

/* ============================== REG ============================== */
{ id:"REG-001", section:"REG", area:"V", tag:"Partner basis",
  front:"Partner outside basis formula (the rollforward)?",
  back:"Beginning basis + contributions + share of income (ordinary + separately stated + tax-exempt) + INCREASE in share of partnership liabilities − distributions − share of losses/nondeductibles − decrease in liability share = ending basis (floor at zero)." },
{ id:"REG-002", section:"REG", area:"V", tag:"Partner basis",
  front:"Do partnership liabilities give the partner basis? What about S-corp debt?",
  back:"Partnership: YES — partners include their share of entity liabilities in outside basis. S corp: NO — shareholders get basis only for DIRECT loans they make to the corporation (debt basis), never for entity-level third-party debt." },
{ id:"REG-003", section:"REG", area:"V", tag:"S corp basis",
  front:"S-corp loss deduction limit and the ordering of basis reduction?",
  back:"Losses are deductible up to STOCK basis, then DEBT basis (direct shareholder loans). Basis ordering each year: + income items first, − distributions, − nondeductibles, − losses." },
{ id:"REG-004", section:"REG", area:"IV", tag:"Loss limits",
  front:"The four loss-limitation hurdles, in order?",
  back:"1) BASIS (outside/stock) → 2) AT-RISK (§465) → 3) PASSIVE activity (§469) → 4) EXCESS BUSINESS LOSS (§461(l), excess becomes NOL). Apply strictly in that order; each suspends what it blocks." },
{ id:"REG-005", section:"REG", area:"IV", tag:"Passive losses",
  front:"When are suspended passive losses freed up?",
  back:"Against passive income as generated, and FULLY RELEASED on a complete taxable disposition of the activity to an unrelated party." },
{ id:"REG-006", section:"REG", area:"V", tag:"C corp",
  front:"C-corp distribution taxation ordering to the shareholder?",
  back:"Dividend to the extent of current + accumulated E&P → then return of capital reducing stock basis → then capital gain for any excess." },
{ id:"REG-007", section:"REG", area:"III", tag:"§1231",
  front:"Why is §1231 the best of both worlds, and what is the lookback?",
  back:"Net §1231 GAIN → long-term capital gain treatment; net §1231 LOSS → ordinary deduction. Lookback: net gain is recharacterized as ORDINARY to the extent of unrecaptured §1231 losses from the prior 5 years." },
{ id:"REG-008", section:"REG", area:"III", tag:"Recapture",
  front:"§1245 vs. §1250 recapture?",
  back:"§1245 (depreciable personalty/equipment): gain is ORDINARY up to ALL depreciation taken. §1250 (depreciable realty): recapture only the excess over straight-line as ordinary; remaining depreciation-related gain = UNRECAPTURED §1250 gain taxed at max 25% (individuals)." },
{ id:"REG-009", section:"REG", area:"III", tag:"§1031",
  front:"§1031 like-kind exchange: what qualifies, and how much gain is recognized when boot is received?",
  back:"Real property held for business/investment (no personalty post-TCJA). Recognized gain = LESSER of realized gain or boot received. Basis of new property = old basis + gain recognized + boot paid − boot received." },
{ id:"REG-010", section:"REG", area:"III", tag:"Installment",
  front:"Installment method: what's recognized each year, and the recapture trap?",
  back:"Gain × (gross profit %) on each payment received. BUT depreciation recapture (§1245/§1250 excess) is recognized in FULL in the year of sale, regardless of cash received. Not available for inventory or dealer property." },
{ id:"REG-011", section:"REG", area:"III", tag:"Related party",
  front:"§267 related-party sale at a loss — treatment?",
  back:"Loss is DISALLOWED. The related buyer may use the disallowed loss to offset GAIN on a later sale to an outsider (but it never creates/increases a loss)." },
{ id:"REG-012", section:"REG", area:"III", tag:"Basis",
  front:"Basis of property received by GIFT vs. by INHERITANCE?",
  back:"Gift: carryover basis (dual-basis rule: if FMV < donor basis at gift, use FMV for computing LOSS, donor basis for GAIN; in between = no gain/loss). Inheritance: stepped to FMV at death (or alternate valuation date), holding period automatically LONG-term." },
{ id:"REG-013", section:"REG", area:"I", tag:"Circular 230",
  front:"What does Circular 230 govern?",
  back:"Practice BEFORE THE IRS by attorneys, CPAs, enrolled agents, etc. — duties (due diligence, no unreasonable delay, fee rules, advertising limits), and sanctions (censure, suspension, disbarment, monetary penalties)." },
{ id:"REG-014", section:"REG", area:"I", tag:"Preparer standards",
  front:"Return-position standards to avoid preparer penalties?",
  back:"Undisclosed position: SUBSTANTIAL AUTHORITY (~40%+ likelihood). Disclosed position (Form 8275): REASONABLE BASIS (~20%+). Tax shelters/reportable transactions: MORE LIKELY THAN NOT (>50%)." },
{ id:"REG-015", section:"REG", area:"I", tag:"Authority",
  front:"Rank federal tax authority (highest first).",
  back:"Internal Revenue Code (statute) & treaties → Treasury regulations (final/temporary) → IRS rulings (Rev. Rul., Rev. Proc.) → case law per court level. Proposed regs and IRS publications carry little/no precedential weight." },
{ id:"REG-016", section:"REG", area:"I", tag:"Procedure",
  front:"Which trial court can a taxpayer use WITHOUT first paying the disputed tax?",
  back:"U.S. TAX COURT (petition within 90 days of the notice of deficiency). District Court and Court of Federal Claims require paying first and suing for refund." },
{ id:"REG-017", section:"REG", area:"I", tag:"FBAR",
  front:"Who must file an FBAR?",
  back:"U.S. persons with a financial interest in or signature authority over foreign financial accounts whose AGGREGATE value exceeds $10,000 at any time during the year (FinCEN Form 114, separate from the tax return)." },
{ id:"REG-018", section:"REG", area:"II", tag:"Contracts",
  front:"Which contracts fall within the Statute of Frauds (writing required)?",
  back:"MYLEGS: Marriage-consideration promises, contracts not performable within one Year, Land interests, Executor's personal promises, Goods ≥ $500 (UCC), Suretyship (answering for another's debt)." },
{ id:"REG-019", section:"REG", area:"II", tag:"Contracts",
  front:"UCC Article 2 vs. common law — scope and a key formation difference?",
  back:"UCC: sales of GOODS (movables); common law: services, land, intangibles. UCC is more flexible — open terms OK, firm offers by merchants irrevocable without consideration (≤3 months), acceptance with additional terms can still form a contract between merchants." },
{ id:"REG-020", section:"REG", area:"II", tag:"Secured transactions",
  front:"Attachment vs. perfection under UCC Article 9?",
  back:"Attachment (enforceable vs. debtor): value given + debtor has rights in collateral + authenticated security agreement (or possession/control). Perfection (priority vs. third parties): filing a financing statement, possession, control, or automatic (PMSI in consumer goods)." },
{ id:"REG-021", section:"REG", area:"II", tag:"Secured transactions",
  front:"PMSI super-priority rules?",
  back:"A purchase-money security interest beats earlier perfected interests: in INVENTORY — perfect BEFORE delivery + notify prior secured parties; in EQUIPMENT/non-inventory — perfect within 20 days after debtor receives possession." },
{ id:"REG-022", section:"REG", area:"II", tag:"Suretyship",
  front:"The surety's four rights?",
  back:"Exoneration (compel debtor to pay), Reimbursement (recover from debtor after paying), Subrogation (step into creditor's rights), Contribution (recover proportionate share from co-sureties)." },
{ id:"REG-023", section:"REG", area:"II", tag:"Bankruptcy",
  front:"Chapters 7, 11, 13 — one line each?",
  back:"Ch. 7: liquidation by a trustee, discharge of remaining debts. Ch. 11: reorganization (usually business; debtor in possession). Ch. 13: individual wage-earner repayment plan (3–5 years), keeps assets." },
{ id:"REG-024", section:"REG", area:"II", tag:"Bankruptcy",
  front:"Simplified priority order of unsecured claims in bankruptcy?",
  back:"Domestic support obligations → administrative expenses → (gap claims in involuntary) → wages (capped, recent) → employee benefit plans → consumer deposits → taxes → general unsecured. Secured creditors take their collateral first." },
{ id:"REG-025", section:"REG", area:"V", tag:"Flow-through",
  front:"What are separately stated items, and why do they exist?",
  back:"Items that could affect different owners differently (capital G/L, §1231, charitable contributions, §179, investment interest, foreign taxes, dividends/interest). They bypass ordinary income and keep their CHARACTER on the owner's K-1 and return." },
{ id:"REG-026", section:"REG", area:"V", tag:"Book-to-tax",
  front:"Schedule M-1 direction: municipal interest, federal income tax expense, excess MACRS?",
  back:"Start with book income. Muni interest: SUBTRACT (in book, not tax). Federal income tax expense: ADD back (book expense, nondeductible). Excess tax depreciation: SUBTRACT (bigger tax deduction than book)." },
{ id:"REG-027", section:"REG", area:"IV", tag:"Estimated tax",
  front:"Individual estimated-tax safe harbors?",
  back:"Pay the lesser of 90% of the current year's tax or 100% of the prior year's tax (110% if prior-year AGI > $150,000) through withholding/estimates to avoid the underpayment penalty." },
{ id:"REG-028", section:"REG", area:"IV", tag:"Individuals",
  front:"Order of the individual tax formula?",
  back:"Gross income − adjustments (above-the-line) = AGI − greater of standard/itemized deductions (− QBI deduction) = taxable income → tax − credits + other taxes − payments = due/refund." },
{ id:"REG-029", section:"REG", area:"V", tag:"S corp eligibility",
  front:"S-corporation eligibility requirements?",
  back:"Domestic corporation; ≤100 shareholders (family members can elect to count as one); shareholders = individuals (US citizens/residents), estates, certain trusts — NO corporations/partnerships/nonresident aliens; ONE class of stock (voting differences OK)." },
{ id:"REG-030", section:"REG", area:"II", tag:"Agency",
  front:"Actual vs. apparent authority?",
  back:"Actual (express/implied): what the principal actually granted. Apparent: what a third party REASONABLY believes from the principal's manifestations — binds the principal even if the agent lacked actual authority. Undisclosed principals: agent also liable." },

/* ============================== BAR ============================== */
{ id:"BAR-001", section:"BAR", area:"I", tag:"Ratios",
  front:"Current ratio vs. quick (acid-test) ratio?",
  back:"Current = current assets / current liabilities. Quick = (cash + marketable securities + net A/R) / current liabilities — strips inventory and prepaids to test immediate liquidity." },
{ id:"BAR-002", section:"BAR", area:"I", tag:"Ratios",
  front:"DuPont decomposition of ROE?",
  back:"ROE = net profit margin (NI/Sales) × asset turnover (Sales/Assets) × equity multiplier (Assets/Equity) — profitability × efficiency × leverage. Diagnose WHICH lever moved." },
{ id:"BAR-003", section:"BAR", area:"I", tag:"Ratios",
  front:"Inventory turnover and days-in-inventory formulas?",
  back:"Inventory turnover = COGS / average inventory. Days = 365 / turnover. (A/R turnover uses net credit sales / average A/R; DSO = 365 / A/R turnover.)" },
{ id:"BAR-004", section:"BAR", area:"I", tag:"CVP",
  front:"Breakeven in units and in dollars?",
  back:"Units = fixed costs / contribution margin per unit. Dollars = fixed costs / CM ratio. Target-profit units = (fixed + target profit) / CM per unit." },
{ id:"BAR-005", section:"BAR", area:"I", tag:"CVP",
  front:"Margin of safety and operating leverage?",
  back:"Margin of safety = actual (or budgeted) sales − breakeven sales. Degree of operating leverage = contribution margin / operating income — high leverage = small sales swings produce big income swings." },
{ id:"BAR-006", section:"BAR", area:"I", tag:"Variances",
  front:"Materials price and usage variance formulas?",
  back:"Price = AQ × (AP − SP) (often at purchase). Usage = SP × (AQ used − SQ allowed). Negative/paid-less or used-less = favorable." },
{ id:"BAR-007", section:"BAR", area:"I", tag:"Variances",
  front:"Labor rate and efficiency variance formulas?",
  back:"Rate = AH × (AR − SR). Efficiency = SR × (AH − SH allowed for actual output)." },
{ id:"BAR-008", section:"BAR", area:"I", tag:"Variances",
  front:"Fixed-overhead volume variance — what causes it?",
  back:"Budgeted fixed OH − APPLIED fixed OH: producing more/less than the denominator level. It signals capacity utilization, not spending control (that's the budget/spending variance)." },
{ id:"BAR-009", section:"BAR", area:"I", tag:"Costing",
  front:"Absorption vs. variable costing — when do incomes differ?",
  back:"Absorption capitalizes fixed OH in inventory; variable expenses it. Production > sales → absorption income HIGHER (fixed OH deferred in inventory); production < sales → absorption LOWER. Equal when production = sales." },
{ id:"BAR-010", section:"BAR", area:"I", tag:"Cost behavior",
  front:"High-low method?",
  back:"Variable rate = (cost at highest activity − cost at lowest) / (highest units − lowest units); fixed = total cost − (variable rate × units) at either point." },
{ id:"BAR-011", section:"BAR", area:"I", tag:"Capital budgeting",
  front:"NPV vs. IRR decision rules, and which wins in a conflict?",
  back:"NPV: accept if > 0 (discounted at cost of capital). IRR: accept if IRR > hurdle rate. When rankings conflict (scale/timing differences), prefer NPV — it assumes reinvestment at the cost of capital and measures value added." },
{ id:"BAR-012", section:"BAR", area:"I", tag:"Capital budgeting",
  front:"Payback period — strengths and blind spots?",
  back:"Simple liquidity/risk screen (time to recover investment) BUT ignores the time value of money and all cash flows after payback. Profitability index = PV of inflows / initial outlay — ranks projects under capital rationing." },
{ id:"BAR-013", section:"BAR", area:"II", tag:"Business combinations",
  front:"Goodwill computation in a business combination (with NCI)?",
  back:"Goodwill = (consideration transferred + fair value of NCI + FV of previously held interest) − fair value of identifiable net assets acquired. If negative → BARGAIN PURCHASE gain to the acquirer (in income)." },
{ id:"BAR-014", section:"BAR", area:"II", tag:"Consolidation",
  front:"Intercompany profit in ending inventory — what do you eliminate, and how does upstream vs. downstream differ?",
  back:"Defer the unrealized profit until sold to outsiders (reduce inventory & COGS adjustments). Downstream (parent→sub): all elimination against the parent/controlling interest. Upstream (sub→parent): allocate the deferral between parent AND NCI." },
{ id:"BAR-015", section:"BAR", area:"II", tag:"Step acquisition",
  front:"Accounting when control is achieved in stages (step acquisition)?",
  back:"REMEASURE the previously held equity interest to fair value at the date control is obtained; recognize the gain/loss in income; then apply acquisition accounting to 100% of identifiable net assets." },
{ id:"BAR-016", section:"BAR", area:"II", tag:"Derivatives",
  front:"Three defining characteristics of a derivative?",
  back:"(1) Underlying + notional amount (or payment provision); (2) little or no initial net investment; (3) net settlement (or can be settled net). Always measured at FAIR VALUE on the balance sheet." },
{ id:"BAR-017", section:"BAR", area:"II", tag:"Hedging",
  front:"Where do gains/losses go: fair-value hedge vs. cash-flow hedge vs. net-investment hedge?",
  back:"Fair-value hedge: derivative AND hedged item both to NET INCOME (offset). Cash-flow hedge: effective portion to OCI, reclassified to income when the hedged transaction affects earnings. Net-investment hedge: effective portion to OCI/CTA." },
{ id:"BAR-018", section:"BAR", area:"II", tag:"Share-based comp",
  front:"Equity-classified stock options — measurement and expense pattern?",
  back:"Measure at GRANT-DATE fair value (option-pricing model); expense over the requisite service (vesting) period; forfeitures by policy (estimate or as-incurred). No remeasurement for equity awards." },
{ id:"BAR-019", section:"BAR", area:"II", tag:"Software/R&D",
  front:"R&D vs. internal-use software vs. software-for-sale cost treatment?",
  back:"R&D: expense as incurred. Internal-use software: capitalize during APPLICATION DEVELOPMENT stage (expense preliminary & post-implementation). Software for sale: expense until TECHNOLOGICAL FEASIBILITY, then capitalize to general release." },
{ id:"BAR-020", section:"BAR", area:"III", tag:"Governmental",
  front:"Fund-balance to government-wide net position: name four reconciling items.",
  back:"+ Capital assets net of depreciation; − long-term liabilities (bonds, compensated absences); ± accrual adjustments (interest payable, unavailable revenue/deferred inflows); + internal service fund net position." },
{ id:"BAR-021", section:"BAR", area:"III", tag:"Governmental",
  front:"Modified accrual: when is revenue recognized, and how are capital outlays and debt proceeds reported in funds?",
  back:"Revenue when MEASURABLE AND AVAILABLE (collectible within the period or soon enough to pay current liabilities). Capital outlay = expenditure (not an asset); debt proceeds = other financing source (not a liability) — both reversed in the government-wide conversion." },
{ id:"BAR-022", section:"BAR", area:"I", tag:"Non-GAAP",
  front:"What should you check when evaluating a non-GAAP measure (e.g., adjusted EBITDA)?",
  back:"Reconciliation to the nearest GAAP measure, consistency period-to-period, whether 'one-time' addbacks recur, and symmetry (excluding losses but keeping gains is a red flag)." },
{ id:"BAR-023", section:"BAR", area:"I", tag:"Forecasting",
  front:"Sensitivity vs. scenario analysis?",
  back:"Sensitivity: flex ONE input at a time to see the effect on the output. Scenario: change a coherent SET of inputs together (best/base/worst). Both test the fragility of forecasts and budgets." },
{ id:"BAR-024", section:"BAR", area:"II", tag:"Lessor",
  front:"Lessor lease classifications and their income patterns?",
  back:"Sales-type: derecognize asset, recognize selling profit + interest income over term. Direct financing: profit deferred into the net investment, interest income over term. Operating: keep the asset, straight-line lease income + depreciation." },
{ id:"BAR-025", section:"BAR", area:"I", tag:"Working capital",
  front:"Cash conversion cycle?",
  back:"Days inventory outstanding + days sales outstanding − days payables outstanding. Shorter = less financing needed; lengthening DPO conserves cash but strains suppliers." },

/* ============================== ISC ============================== */
{ id:"ISC-001", section:"ISC", area:"III", tag:"SOC",
  front:"SOC 1 vs. SOC 2 vs. SOC 3 — purpose and audience?",
  back:"SOC 1: controls relevant to user entities' FINANCIAL REPORTING (ICFR); restricted to user entities & their auditors. SOC 2: controls vs. Trust Services Criteria (security etc.); restricted to knowledgeable parties. SOC 3: same scope as SOC 2 but GENERAL-USE/public summary." },
{ id:"ISC-002", section:"ISC", area:"III", tag:"SOC",
  front:"Type 1 vs. Type 2 SOC report?",
  back:"Type 1: design suitability at a POINT IN TIME. Type 2: design AND operating effectiveness over a PERIOD (what auditors need for control reliance). SOC 3 is only issued as Type 2-based." },
{ id:"ISC-003", section:"ISC", area:"III", tag:"SOC",
  front:"What are CUECs?",
  back:"Complementary User-Entity Controls — controls the USER organization must implement for the service organization's controls to achieve their objectives (e.g., the user manages its own user-access approvals). Listed in the SOC report; user auditors must evaluate them." },
{ id:"ISC-004", section:"ISC", area:"III", tag:"SOC",
  front:"Carve-out vs. inclusive method for subservice organizations?",
  back:"Carve-out: subservice org's controls EXCLUDED from the description/testing; report identifies relevant CSOCs. Inclusive: subservice org's controls INCLUDED in the description and covered by the examination." },
{ id:"ISC-005", section:"ISC", area:"III", tag:"TSC",
  front:"The five Trust Services Criteria categories — and which is mandatory?",
  back:"Security (the COMMON CRITERIA — always in scope), Availability, Processing Integrity, Confidentiality, Privacy. The other four are added per engagement scope." },
{ id:"ISC-006", section:"ISC", area:"II", tag:"Privacy",
  front:"Confidentiality vs. privacy in the TSC sense?",
  back:"Confidentiality: protecting any information designated confidential (business data, trade secrets). Privacy: specifically PERSONAL information — its collection, use, retention, disclosure, and disposal per commitments and criteria." },
{ id:"ISC-007", section:"ISC", area:"II", tag:"Frameworks",
  front:"The six NIST CSF 2.0 functions (and which is new in 2.0)?",
  back:"GOVERN (new in 2.0) + Identify, Protect, Detect, Respond, Recover. Govern wraps strategy, roles, oversight, and supply-chain risk around the other five." },
{ id:"ISC-008", section:"ISC", area:"II", tag:"Frameworks",
  front:"One-line purpose: COBIT vs. CIS Controls vs. ISO 27001?",
  back:"COBIT (ISACA): governance & management of enterprise IT — aligning IT with business objectives. CIS Controls: prioritized, prescriptive technical safeguards/hardening baselines. ISO 27001: certifiable information-security management system (ISMS) standard." },
{ id:"ISC-009", section:"ISC", area:"II", tag:"IAM",
  front:"Authentication vs. authorization?",
  back:"Authentication (AuthN): proving WHO you are — passwords, MFA, biometrics. Authorization (AuthZ): WHAT you may do — permissions/roles applied after identity is established." },
{ id:"ISC-010", section:"ISC", area:"II", tag:"IAM",
  front:"Least privilege and segregation of duties (in IT terms)?",
  back:"Least privilege: grant the minimum access a role requires, nothing more. SoD: split incompatible duties (e.g., developer cannot promote own code to production; same person can't create vendors AND approve payments) — enforced via roles and workflow." },
{ id:"ISC-011", section:"ISC", area:"II", tag:"IAM",
  front:"Provisioning/deprovisioning and privileged access management?",
  back:"Joiner-mover-leaver process: grant access on hire, adjust on transfer, REMOVE PROMPTLY on exit (stale accounts = classic finding). PAM: extra controls on admin accounts — vaulting, check-out, session logging, MFA." },
{ id:"ISC-012", section:"ISC", area:"II", tag:"Controls",
  front:"Preventive vs. detective vs. corrective controls — one example each?",
  back:"Preventive: stop it happening (access control, input validation). Detective: find it after (log review, reconciliations, IDS). Corrective: fix/restore (backups & restore, incident response, patching)." },
{ id:"ISC-013", section:"ISC", area:"II", tag:"Encryption",
  front:"Symmetric vs. asymmetric encryption; what is hashing for?",
  back:"Symmetric: one shared key — fast, key-distribution problem (AES). Asymmetric: public/private key pair — enables exchange & digital signatures (RSA). Hashing: one-way fingerprint for INTEGRITY verification (not encryption; not reversible)." },
{ id:"ISC-014", section:"ISC", area:"II", tag:"Incident response",
  front:"Incident-response lifecycle stages?",
  back:"Preparation → Identification/Detection → Containment → Eradication → Recovery → Lessons learned (post-incident review). Containment before eradication — stop the bleeding first." },
{ id:"ISC-015", section:"ISC", area:"I", tag:"Data lifecycle",
  front:"Stages of the data life cycle?",
  back:"Collect/capture → store/maintain → use/process → share/disclose → archive/retain → destroy/dispose — with controls at each stage (validation, encryption at rest/in transit, retention policy, secure disposal)." },
{ id:"ISC-016", section:"ISC", area:"I", tag:"Data quality",
  front:"Name four data-quality dimensions.",
  back:"Accuracy, completeness, consistency, timeliness (also validity and uniqueness). Data governance assigns OWNERSHIP and STEWARDSHIP to keep them enforced." },
{ id:"ISC-017", section:"ISC", area:"I", tag:"Cloud",
  front:"IaaS vs. PaaS vs. SaaS — who manages what?",
  back:"IaaS: provider supplies infrastructure (compute/storage/network); you manage OS and up. PaaS: provider manages platform/runtime; you manage your application & data. SaaS: provider runs the whole application; you manage data, users, and configuration. Security is always SHARED." },
{ id:"ISC-018", section:"ISC", area:"I", tag:"ITGC",
  front:"The classic ITGC domains?",
  back:"(1) Access to programs & data (logical security), (2) program CHANGE MANAGEMENT (authorize-test-approve-migrate, segregation of dev/prod), (3) computer operations (job scheduling, backups, incident handling), (+ program development/SDLC)." },
{ id:"ISC-019", section:"ISC", area:"I", tag:"Database",
  front:"Primary key vs. foreign key; what does normalization do?",
  back:"Primary key: unique identifier of a table row. Foreign key: field referencing another table's primary key — enforces referential integrity. Normalization: organizing tables to remove redundancy/update anomalies." },
{ id:"ISC-020", section:"ISC", area:"I", tag:"SQL",
  front:"What do SELECT, WHERE, JOIN, and GROUP BY each do?",
  back:"SELECT: choose columns. WHERE: filter rows by condition. JOIN: combine tables on matching keys. GROUP BY: aggregate rows (with SUM/COUNT/AVG); HAVING filters the aggregated groups." },
{ id:"ISC-021", section:"ISC", area:"II", tag:"Threats",
  front:"Phishing vs. SQL injection vs. ransomware — and one mitigation each?",
  back:"Phishing: deceptive messages harvesting credentials → training + MFA. SQL injection: malicious input manipulating queries → input validation/parameterized queries. Ransomware: encrypts data for ransom → offline/immutable backups + patching + EDR." },
{ id:"ISC-022", section:"ISC", area:"II", tag:"Privacy law",
  front:"GDPR essentials a CPA should know?",
  back:"EU personal data, extraterritorial reach; requires a lawful basis for processing; data-subject rights (access, erasure, portability); 72-HOUR breach notification to supervisory authority; heavy fines (up to 4% of global revenue)." },
{ id:"ISC-023", section:"ISC", area:"II", tag:"Privacy law",
  front:"HIPAA vs. PCI-DSS vs. GLBA — what data does each cover?",
  back:"HIPAA: protected HEALTH information (PHI) — privacy & security rules + breach notification. PCI-DSS: PAYMENT-CARD data — 12 contractual requirements for the cardholder-data environment. GLBA: financial institutions' CUSTOMER financial data — safeguards rule + privacy notices." },
{ id:"ISC-024", section:"ISC", area:"I", tag:"Change mgmt",
  front:"A sound program change-management process?",
  back:"Authorized request → developed/tested in NON-production → independent review/approval → migration to production by someone OTHER than the developer → documentation & rollback plan. Emergency changes: act fast but document and approve after the fact." },
{ id:"ISC-025", section:"ISC", area:"I", tag:"Blockchain",
  front:"Blockchain in one line + two risks the exam cares about?",
  back:"A distributed, append-only ledger validated by consensus. Risks: key management (lost/stolen private keys), smart-contract/code flaws, governance/irreversibility of errors — 'immutable' includes immutable mistakes." },
{ id:"ISC-026", section:"ISC", area:"II", tag:"Network",
  front:"Firewall, IDS/IPS, segmentation, VPN — one line each?",
  back:"Firewall: filters traffic by rules at the boundary. IDS: detects suspicious traffic (alerts); IPS: blocks it inline. Segmentation: isolates network zones to limit lateral movement. VPN: encrypted tunnel for remote access." },
{ id:"ISC-027", section:"ISC", area:"II", tag:"Resilience",
  front:"RPO vs. RTO; backup strategies?",
  back:"RPO: max acceptable DATA loss (how recent the backup must be). RTO: max acceptable DOWNTIME (how fast you must restore). Strategies: full/incremental/differential backups; hot/warm/cold sites for disaster recovery." },
{ id:"ISC-028", section:"ISC", area:"III", tag:"SOC",
  front:"SOC for Cybersecurity vs. SOC 2?",
  back:"SOC for Cybersecurity: ENTITY-WIDE cybersecurity risk-management program report, broad/general audience. SOC 2: a SERVICE ORGANIZATION'S system controls vs. Trust Services Criteria for specified users." },

/* ============================== TCP ============================== */
{ id:"TCP-001", section:"TCP", area:"II", tag:"S corp AAA",
  front:"What is AAA and the S-corp distribution ordering when the company has old C-corp E&P?",
  back:"AAA = Accumulated Adjustments Account, tracking post-election undistributed S income. Distributions: (1) tax-free from AAA to extent of stock basis → (2) DIVIDEND from accumulated C-corp E&P → (3) return of capital against remaining basis → (4) capital gain." },
{ id:"TCP-002", section:"TCP", area:"II", tag:"Debt basis",
  front:"S-corp losses reduced debt basis in a prior year. What happens when the corporation later has income?",
  back:"Net increases RESTORE DEBT BASIS FIRST (up to its original amount) before increasing stock basis. Repayment of a shareholder loan while debt basis is reduced triggers gain." },
{ id:"TCP-003", section:"TCP", area:"III", tag:"Entity selection",
  front:"Which entity form minimizes self-employment tax for an active owner, and what's the catch?",
  back:"S corporation — distributions are not subject to SE/payroll tax. Catch: the owner-employee must take REASONABLE COMPENSATION as W-2 wages first; the IRS attacks low-salary/high-distribution patterns." },
{ id:"TCP-004", section:"TCP", area:"III", tag:"Entity selection",
  front:"Which entity allows special (disproportionate) allocations? Which is required for QSBS?",
  back:"Partnerships/LLCs can specially allocate income/loss if allocations have substantial economic effect (§704(b)). §1202 QSBS requires a domestic C CORPORATION — S corps and partnerships don't qualify." },
{ id:"TCP-005", section:"TCP", area:"I", tag:"Equity comp",
  front:"ISO taxation at grant, exercise, and sale (holding requirements met)?",
  back:"Grant: nothing. Exercise: nothing for REGULAR tax, but the bargain element (FMV − strike) is an AMT preference. Sale after holding ≥2 yrs from grant AND ≥1 yr from exercise: entire gain = LONG-TERM CAPITAL GAIN." },
{ id:"TCP-006", section:"TCP", area:"I", tag:"Equity comp",
  front:"What is a disqualifying disposition of ISO stock?",
  back:"Selling before the 2-year-from-grant / 1-year-from-exercise holding periods → the bargain element becomes ORDINARY income in the year of sale (W-2 character), remainder capital gain. The AMT adjustment reverses." },
{ id:"TCP-007", section:"TCP", area:"I", tag:"Equity comp",
  front:"NQSO and RSU taxation timing?",
  back:"NQSO: ORDINARY income at EXERCISE = FMV − strike (W-2); later appreciation = capital gain (basis = FMV at exercise). RSU: ordinary income at VESTING = FMV; capital gain/loss after. Neither has the ISO AMT preference." },
{ id:"TCP-008", section:"TCP", area:"I", tag:"§83(b)",
  front:"What does a §83(b) election do, and the risk?",
  back:"Elect (within 30 days of grant) to be taxed NOW on restricted stock's current FMV → starts the capital-gain holding period and locks in a low ordinary amount. Risk: if forfeited or value falls, the tax paid is NOT refundable." },
{ id:"TCP-009", section:"TCP", area:"I", tag:"AMT",
  front:"The AMT computation flow?",
  back:"Regular taxable income ± adjustments + preferences = AMTI − exemption (phases out at high income) × 26%/28% = tentative minimum tax. Pay AMT = excess of TMT over regular tax. ISO exercises and private-activity bond interest are classic triggers." },
{ id:"TCP-010", section:"TCP", area:"I", tag:"Estimated tax",
  front:"High-income individual estimated-tax safe harbor?",
  back:"Lesser of 90% of current-year tax or 110% of PRIOR-year tax (the 110% applies when prior-year AGI exceeds $150,000; otherwise 100%)." },
{ id:"TCP-011", section:"TCP", area:"I", tag:"Charitable",
  front:"Best asset to give to charity: cash or appreciated long-term stock? Why?",
  back:"Appreciated LONG-TERM stock — deduct full FMV (up to 30%-of-AGI limit for appreciated property to public charities) AND never pay tax on the built-in gain. Loss property: sell first (harvest the loss), then give cash." },
{ id:"TCP-012", section:"TCP", area:"II", tag:"Trusts",
  front:"What is DNI and what two things does it cap?",
  back:"Distributable Net Income ≈ trust taxable income before the distribution deduction, + tax-exempt interest, − capital gains allocated to corpus. It caps BOTH the trust's distribution deduction AND the amount taxable to beneficiaries — and it carries CHARACTER through." },
{ id:"TCP-013", section:"TCP", area:"II", tag:"Trusts",
  front:"Simple vs. complex trust?",
  back:"Simple: REQUIRED to distribute all income currently, no corpus distributions, no charitable gifts (that year). Complex: may accumulate income, distribute corpus, or give to charity. Trusts hit the TOP bracket at very low income → distribute to lower-bracket beneficiaries." },
{ id:"TCP-014", section:"TCP", area:"I", tag:"Gift tax",
  front:"Annual exclusion mechanics and gift-splitting?",
  back:"Each donor can give the annual exclusion amount (indexed) per DONEE per year free of gift tax, for present interests only. Married couples can elect GIFT-SPLITTING to treat gifts as half from each spouse → doubles the exclusion. Excess uses the lifetime unified exemption." },
{ id:"TCP-015", section:"TCP", area:"I", tag:"Estate/gift",
  front:"The unified transfer tax system in one breath?",
  back:"Lifetime taxable gifts and the estate at death share ONE unified exemption and rate schedule; gift tax paid is a credit. Unlimited MARITAL and CHARITABLE deductions. GST tax adds a separate layer for transfers skipping a generation." },
{ id:"TCP-016", section:"TCP", area:"IV", tag:"Basis planning",
  front:"Planning: which assets to GIFT during life vs. HOLD until death?",
  back:"Hold highly APPRECIATED assets until death → heirs get a STEPPED-UP basis (gain disappears). Gift assets likely to appreciate FURTHER (removes growth from the estate) — but gifts carry CARRYOVER basis. Never gift loss property (dual-basis wastes the loss — sell it yourself)." },
{ id:"TCP-017", section:"TCP", area:"IV", tag:"§1033",
  front:"Involuntary conversion (§1033) deferral rules?",
  back:"Gain deferred if proceeds are reinvested in qualifying similar-use property within the replacement period (generally 2 years after year-end of gain realization; 3 for condemned business realty). Recognize gain only to the extent proceeds are NOT reinvested." },
{ id:"TCP-018", section:"TCP", area:"IV", tag:"Installment",
  front:"When is the installment method a good planning tool — and when is it a trap?",
  back:"Good: spreads gain across years, smooths brackets, defers tax to match cash. Traps: ALL depreciation recapture is taxed in year 1; related-party resale within 2 years accelerates gain; can elect OUT if rates are expected to rise." },
{ id:"TCP-019", section:"TCP", area:"IV", tag:"§1202",
  front:"§1202 QSBS — the core requirements (and the OBBBA wrinkle)?",
  back:"Original-issue stock of a domestic C corp, active qualified business, gross-asset limit at issuance. Pre-OBBBA stock: 100% exclusion at 5-year holding ($50M asset cap). Stock acquired after 7/4/2025: TIERED 50%/75%/100% at 3/4/5 years, $15M per-issuer cap, $75M asset limit. OBBBA rules testable on the exam starting July 1, 2026." },
{ id:"TCP-020", section:"TCP", area:"II", tag:"C corp NOL",
  front:"C-corp NOL rules (post-2017 losses)?",
  back:"No carryback (generally); carry FORWARD indefinitely; deduction limited to 80% of taxable income in the carryforward year. Planning: time income recognition to absorb NOLs efficiently." },
{ id:"TCP-021", section:"TCP", area:"I", tag:"Passive",
  front:"Client has large suspended passive losses and wants them freed — the cleanest planning move?",
  back:"Fully dispose of the entire activity in a taxable sale to an unrelated party → ALL suspended losses for that activity release (first against the gain, then other passive income, then nonpassive). Generating passive income (e.g., another rental's profit) also absorbs them year by year." },
{ id:"TCP-022", section:"TCP", area:"III", tag:"Liquidation",
  front:"Tax consequences when a C corporation liquidates?",
  back:"DOUBLE tax: the corporation recognizes gain/loss as if assets were sold at FMV; shareholders treat distributions as full payment for stock → capital gain/loss (FMV − stock basis). A big reason appreciated-asset businesses avoid C status when an exit is planned." },
{ id:"TCP-023", section:"TCP", area:"II", tag:"Exempt orgs",
  front:"What is UBTI (unrelated business taxable income) for a tax-exempt organization?",
  back:"Income from a TRADE OR BUSINESS regularly carried on that is NOT substantially related to the exempt purpose → taxed at corporate rates. Exclusions: dividends, interest, royalties, most rents from real property; debt-financed income is partially taxable." },
{ id:"TCP-024", section:"TCP", area:"I", tag:"Retirement",
  front:"Traditional vs. Roth contribution planning logic?",
  back:"Traditional: deduct now, taxed on withdrawal — wins if retirement bracket will be LOWER. Roth: no deduction now, tax-free qualified withdrawals — wins if current bracket is lower or for tax diversification; no RMDs for the owner. Backdoor Roth: nondeductible traditional → convert (watch the pro-rata rule)." },
{ id:"TCP-025", section:"TCP", area:"IV", tag:"Related party",
  front:"Imputed interest on below-market loans — the concept?",
  back:"For below-AFR loans (gift loans, compensation loans), the tax law IMPUTES interest: lender recognizes interest income, borrower may deduct (if otherwise allowed), and the foregone interest is treated as a gift/compensation. De minimis exceptions exist (e.g., ≤$10k gift loans)." }
];
